def binary_search(items, target):
    first = 0
    last = len(items) - 1
    found = -1
    while first <= last and found == -1:
        mid = (first + last) // 2
        if items[mid] < target:
            first = mid + 1
        elif items[mid] > target:
            last = mid - 1
        else:
            found = mid
    return found

