def row(size, linear, binary, selection, bubble):
    """Print one line of the table, each value at the right of a column 10 wide."""
    print(f"{size:>10}{linear:>10}{binary:>10}{selection:>10}{bubble:>10}")


def linear_count(items, target):
    count = 0
    for position in range(len(items)):
        count = count + 1
        if items[position] == target:
            return count
    return count


def binary_count(items, target):
    count = 0
    low, high = 0, len(items) - 1
    while low <= high:
        count += 1
        mid = (low + high) // 2
        if items[mid] < target:
            low = mid + 1
        elif items[mid] > target:
            high = mid - 1
        else:
            return count
    return count


def selection_count(items):
    n = len(items)
    return n * (n - 1) // 2


def bubble_count(items):
    work = items[:]
    count = 0
    passes = 0
    swapped = True
    while swapped:
        swapped = False
        for i in range(len(work) - 1 - passes):
            count += 1
            if work[i] > work[i + 1]:
                work[i], work[i + 1] = work[i + 1], work[i]
                swapped = True
        passes += 1
    return count


